using System.Text;
using SentienceJP.Core.Payload;

namespace SentienceJP.Core.Tests.TestSupport;

/// <summary>
/// テスト用の偽のゲームフォルダとペイロードを作る補助。
/// 実ゲームのファイルは使わず（リポジトリにも含めず）、同じ構造の合成データで再現する。
/// </summary>
internal static class FakeGame
{
    /// <summary>
    /// RPGツクールMV の plugins.js と同じ構造の合成データ（LF 改行・末尾改行あり）。
    /// 文字列中の括弧やエスケープされた引用符も含め、パーサの頑健性を確認できるようにしている。
    /// </summary>
    public const string SamplePluginsJs =
        "// Generated by RPG Maker.\n" +
        "// Do not edit this file directly.\n" +
        "var $plugins =\n" +
        "[\n" +
        "{\"name\":\"PluginA\",\"status\":true,\"description\":\"A [test] {plugin}\",\"parameters\":{\"Text\":\"He said \\\"hi\\\" ]\",\"Other\":\"}\"}},\n" +
        "{\"name\":\"PluginB\",\"status\":false,\"description\":\"\",\"parameters\":{}},\n" +
        "{\"name\":\"PluginC\",\"status\":true,\"description\":\"日本語の説明\",\"parameters\":{\"List\":\"[1,2,3]\"}}\n" +
        "];\n";

    /// <summary>テスト用のプラグインのエントリ。</summary>
    public const string PluginEntryJson =
        "{\"name\":\"SentienceJP\",\"status\":true,\"description\":\"Sentience 日本語化パッチ（非公式）\",\"parameters\":{}}";

    /// <summary>ペイロードに含めるテスト用ファイル（入れ子のフォルダ作成も確認できる構成）。</summary>
    public static readonly IReadOnlyDictionary<string, string> PayloadFiles = new Dictionary<string, string>
    {
        ["www/js/plugins/SentienceJP.js"] = "// test plugin\n",
        ["www/sentience_jp/translation.json"] = "{\"m:abc\":\"こんにちは\"}",
        ["www/sentience_jp/fonts/readme.txt"] = "font license",
    };

    /// <summary>偽のゲームフォルダを作る。</summary>
    /// <param name="root">ゲームのルートにするフォルダ。</param>
    /// <param name="pluginsJs">plugins.js の内容（省略時は <see cref="SamplePluginsJs"/>）。</param>
    public static string CreateGame(string root, string? pluginsJs = null)
    {
        WriteText(root, "nw.exe", "fake exe");
        WriteText(root, "www/data/System.json", "{\"gameTitle\":\"Fake\"}");
        WriteText(root, "www/js/plugins/PluginA.js", "// existing plugin");
        WriteText(root, GameConstants.PluginsJsRelativePath, pluginsJs ?? SamplePluginsJs);
        return root;
    }

    /// <summary>
    /// フォルダ構成のペイロードを作って読み込む。
    /// </summary>
    /// <param name="directory">ペイロードを置くフォルダ。</param>
    /// <param name="patchVersion">パッチのバージョン。</param>
    /// <param name="knownPluginsJsSha256">動作確認済みの plugins.js のハッシュ。</param>
    /// <param name="files">ペイロードのファイル（省略時は <see cref="PayloadFiles"/>）。</param>
    public static PayloadBundle CreatePayload(
        string directory,
        string patchVersion = "0.1.0",
        IReadOnlyList<string>? knownPluginsJsSha256 = null,
        IReadOnlyDictionary<string, string>? files = null)
    {
        var contents = files ?? PayloadFiles;
        foreach (var (path, text) in contents)
        {
            WriteText(Path.Combine(directory, "game"), path, text);
        }

        var manifest = BuildManifestJson(patchVersion, contents, knownPluginsJsSha256 ?? []);
        File.WriteAllText(Path.Combine(directory, "manifest.json"), manifest, new UTF8Encoding(false));
        return PayloadBundle.Load(new DirectoryPayloadSource(directory));
    }

    /// <summary>manifest.json の内容を作る。</summary>
    public static string BuildManifestJson(string patchVersion, IReadOnlyDictionary<string, string> files, IReadOnlyList<string> knownPluginsJsSha256)
    {
        var fileEntries = files.Select(pair =>
        {
            var bytes = new UTF8Encoding(false).GetBytes(pair.Value);
            return $"{{\"path\":\"{pair.Key}\",\"sha256\":\"{Hashing.Sha256Hex(bytes)}\",\"size\":{bytes.Length}}}";
        });
        var known = string.Join(",", knownPluginsJsSha256.Select(h => $"\"{h}\""));
        return "{" +
               "\"schema\":1," +
               $"\"patchVersion\":\"{patchVersion}\"," +
               "\"translationVersion\":\"2026.11.21\"," +
               $"\"pluginEntry\":{PluginEntryJson}," +
               $"\"files\":[{string.Join(",", fileEntries)}]," +
               $"\"knownPluginsJsSha256\":[{known}]," +
               "\"knownBuildIds\":[\"2476493\"]" +
               "}";
    }

    /// <summary>UTF-8（BOM なし）でテキストを書く。フォルダが無ければ作る。</summary>
    public static void WriteText(string root, string relativePath, string text)
    {
        var fullPath = Path.Combine(root, relativePath.Replace('/', Path.DirectorySeparatorChar));
        Directory.CreateDirectory(Path.GetDirectoryName(fullPath)!);
        File.WriteAllText(fullPath, text, new UTF8Encoding(false));
    }
}
